CREATE VIEW fhir.patientIdentifierView 
AS 
--EXECUTE AS User = 'analystUser'
SELECT
patient_id,
    birthDate,
    deceasedDateTime,
    gender,
    maritalStatus_text,
    maritalStatus_coding_code,
    maritalStatus_coding_display,
    maritalStatus_coding_system,
    multipleBirthBoolean,
    multipleBirthInteger,
    resourceType,
    text_div,
    text_status,
    identifier_system,
    identifier_type_coding_code,
    identifier_type_coding_system,
    case 
            when IS_MEMBER('businessAnalyst') = 1 then null 
            else identifier_type_text 
      end as identifier_type_text,
    case 
            when IS_MEMBER('dataAnalyst') = 1 and identifier_type_text in ('Driver''s License', 'Medical Record Number', 'Passport Number') then 'xxxx'
            when IS_MEMBER('dataAnalyst') = 1 and identifier_type_text = 'Social Security Number' then concat(substring(identifier_value, 1, 3), '-xx-xxxx') 
            when IS_MEMBER('businessAnalyst') = 1 then null
            else identifier_value 
      end as identifier_value ,
    name_family,
    name_given,
    name_prefix,
    name_suffix,
    name_use,
    telecom_system,
    telecom_use,
    telecom_value,
    communication_language_text,
    communication_language_coding_code,
    communication_language_coding_display,
    communication_language_coding_system
FROM  
fhir.patientIdentifier;

CREATE PROCEDURE fhir.deleteExpiredFactData AS

BEGIN

DECLARE @today date;
DECLARE @year varchar(4);
DECLARE @month varchar(2);
DECLARE @day varchar(2);
DECLARE @purgeDate date;

--SET @today = DATEADD(Year,-5,GETDATE());
SET @today = DATEADD(year, -5, cast('20211231' as date))
SET @year = (select cast(datepart(year, @today) as varchar(4)));
SET @month = (RIGHT('00' + CONVERT(NVARCHAR(2), DATEPART(MONTH, @today)), 2));
SET @day = (RIGHT('00' + CONVERT(NVARCHAR(2), DATEPART(DAY, @today)), 2));

SET @purgeDate = cast(@year + @month + @day as date);

DELETE from fhir.claimMain where cast(cast(year as varchar(4)) + month + day as date) <= @purgeDate;
DELETE from fhir.observationMain where cast(cast(year as varchar(4)) + month + day as date) <= @purgeDate;

END;

